-- Process-specific after-sales actions. Financial execution remains server/provider-owned.

CREATE OR REPLACE FUNCTION private.can_after_sales_case_permission(p_case_id uuid, p_permission text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO public, private, pg_catalog
AS $function$
  SELECT private.is_platform_admin() OR EXISTS (
    SELECT 1 FROM public.after_sales_cases c
    JOIN public.organization_shop_links osl ON osl.shop_id = c.shop_id
    WHERE c.id = p_case_id AND private.organization_has_permission(osl.organization_id, p_permission)
  );
$function$;

CREATE OR REPLACE FUNCTION public.receive_my_after_sales_return(p_case_id uuid, p_note text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public, private, pg_catalog
AS $function$
DECLARE v_case_number text;
BEGIN
  IF auth.uid() IS NULL OR NOT (private.can_after_sales_case_permission(p_case_id, 'MANAGE_CLAIMS') OR private.can_after_sales_case_permission(p_case_id, 'APPROVE_RETURN')) THEN RAISE EXCEPTION 'return management permission required'; END IF;
  SELECT c.case_number INTO v_case_number FROM public.after_sales_cases c WHERE c.id = p_case_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'case not found'; END IF;
  UPDATE public.return_shipments SET status = 'received', received_at = COALESCE(received_at, timezone('utc', now()))
  WHERE case_id = p_case_id AND status IN ('shipped', 'in_transit');
  IF NOT FOUND THEN RAISE EXCEPTION 'return shipment is not awaiting receipt'; END IF;
  PERFORM private.append_after_sales_case_event(p_case_id, 'return_received', auth.uid(), COALESCE(NULLIF(trim(p_note), ''), 'รับสินค้าคืนแล้ว'), 'RETURN_RECEIVED:' || p_case_id::text);
  PERFORM private.notify_after_sales_customer(p_case_id, 'RETURN_RECEIVED', 'รับสินค้าคืนแล้ว', 'ทีมงานได้รับสินค้าคืนและกำลังตรวจสอบ', 'RETURN_RECEIVED_NOTIFICATION:' || p_case_id::text);
END;
$function$;

CREATE OR REPLACE FUNCTION public.inspect_my_after_sales_return(p_case_id uuid, p_result text, p_note text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public, private, pg_catalog
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT private.can_after_sales_case_permission(p_case_id, 'APPROVE_RETURN') THEN RAISE EXCEPTION 'return inspection approval required'; END IF;
  IF p_result NOT IN ('accepted', 'rejected') THEN RAISE EXCEPTION 'invalid inspection result'; END IF;
  UPDATE public.return_shipments SET status = CASE WHEN p_result = 'accepted' THEN 'completed' ELSE 'failed' END,
    metadata = metadata || jsonb_build_object('inspection_result', p_result, 'inspection_note', NULLIF(trim(p_note), ''), 'inspected_by', auth.uid(), 'inspected_at', timezone('utc', now()))
  WHERE case_id = p_case_id AND status IN ('received', 'inspection');
  IF NOT FOUND THEN RAISE EXCEPTION 'return shipment must be received before inspection'; END IF;
  PERFORM private.append_after_sales_case_event(p_case_id, 'return_inspected', auth.uid(), COALESCE(NULLIF(trim(p_note), ''), 'ตรวจสอบสินค้าคืนแล้ว'), 'RETURN_INSPECTED:' || p_case_id::text || ':' || p_result, jsonb_build_object('result', p_result));
  PERFORM private.notify_after_sales_customer(p_case_id, 'RETURN_INSPECTED', 'อัปเดตการตรวจสอบสินค้าคืน', CASE WHEN p_result = 'accepted' THEN 'สินค้าคืนผ่านการตรวจสอบแล้ว' ELSE 'สินค้าคืนต้องการการตรวจสอบเพิ่มเติม' END, 'RETURN_INSPECTED_NOTIFICATION:' || p_case_id::text || ':' || p_result);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_my_after_sales_refund_status(p_refund_id uuid, p_next_status text, p_provider_reference text DEFAULT NULL, p_note text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public, private, pg_catalog
AS $function$
DECLARE v_case_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT private.is_platform_admin() THEN RAISE EXCEPTION 'platform finance approval required'; END IF;
  IF p_next_status NOT IN ('processing', 'completed', 'failed') THEN RAISE EXCEPTION 'invalid refund transition'; END IF;
  SELECT case_id INTO v_case_id FROM public.after_sales_refunds WHERE id = p_refund_id AND status IN ('approved', 'processing') FOR UPDATE;
  IF v_case_id IS NULL THEN RAISE EXCEPTION 'refund is not available for this transition'; END IF;
  UPDATE public.after_sales_refunds SET status = p_next_status, provider_reference = COALESCE(NULLIF(trim(p_provider_reference), ''), provider_reference), completed_at = CASE WHEN p_next_status = 'completed' THEN timezone('utc', now()) ELSE completed_at END WHERE id = p_refund_id;
  PERFORM private.append_after_sales_case_event(v_case_id, CASE WHEN p_next_status = 'completed' THEN 'refund_completed' WHEN p_next_status = 'failed' THEN 'refund_failed' ELSE 'refund_processing' END, auth.uid(), NULLIF(trim(p_note), ''), 'REFUND_STATUS:' || p_refund_id::text || ':' || p_next_status, jsonb_build_object('refund_id', p_refund_id));
  PERFORM private.notify_after_sales_customer(v_case_id, 'REFUND_' || upper(p_next_status), CASE WHEN p_next_status = 'completed' THEN 'คืนเงินสำเร็จ' WHEN p_next_status = 'failed' THEN 'การคืนเงินต้องตรวจสอบเพิ่มเติม' ELSE 'กำลังดำเนินการคืนเงิน' END, COALESCE(NULLIF(trim(p_note), ''), 'ติดตามสถานะได้จากรายละเอียดคำร้อง'), 'REFUND_STATUS_NOTIFICATION:' || p_refund_id::text || ':' || p_next_status);
END;
$function$;

CREATE OR REPLACE FUNCTION public.ship_my_after_sales_replacement(p_case_id uuid, p_provider text, p_tracking_number text, p_tracking_url text DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public, private, pg_catalog
AS $function$
DECLARE v_id uuid; v_shop_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT private.can_after_sales_case_permission(p_case_id, 'APPROVE_REPLACEMENT') THEN RAISE EXCEPTION 'replacement fulfilment permission required'; END IF;
  SELECT shop_id INTO v_shop_id FROM public.after_sales_cases WHERE id = p_case_id AND requested_resolution IN ('replacement', 'reship_missing_item') AND status IN ('approved', 'in_progress');
  IF v_shop_id IS NULL THEN RAISE EXCEPTION 'replacement is not approved for this case'; END IF;
  IF NULLIF(trim(p_provider), '') IS NULL OR NULLIF(trim(p_tracking_number), '') IS NULL THEN RAISE EXCEPTION 'provider and tracking number are required'; END IF;
  INSERT INTO public.replacement_shipments (case_id, shop_id, provider, tracking_number, tracking_url, status, shipped_at)
  VALUES (p_case_id, v_shop_id, trim(p_provider), trim(p_tracking_number), NULLIF(trim(p_tracking_url), ''), 'shipped', timezone('utc', now()))
  ON CONFLICT (case_id) DO UPDATE SET provider = EXCLUDED.provider, tracking_number = EXCLUDED.tracking_number, tracking_url = EXCLUDED.tracking_url, status = 'shipped', shipped_at = COALESCE(public.replacement_shipments.shipped_at, EXCLUDED.shipped_at), updated_at = timezone('utc', now())
  RETURNING id INTO v_id;
  PERFORM private.append_after_sales_case_event(p_case_id, 'replacement_shipped', auth.uid(), 'ส่งสินค้าทดแทนแล้ว', 'REPLACEMENT_SHIPPED:' || p_case_id::text);
  PERFORM private.notify_after_sales_customer(p_case_id, 'REPLACEMENT_SHIPPED', 'ส่งสินค้าทดแทนแล้ว', 'คุณสามารถติดตามเลขพัสดุสินค้าทดแทนได้', 'REPLACEMENT_SHIPPED_NOTIFICATION:' || p_case_id::text);
  RETURN v_id;
END;
$function$;

REVOKE ALL ON FUNCTION public.receive_my_after_sales_return(uuid, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.inspect_my_after_sales_return(uuid, text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.update_my_after_sales_refund_status(uuid, text, text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.ship_my_after_sales_replacement(uuid, text, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.receive_my_after_sales_return(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.inspect_my_after_sales_return(uuid, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_my_after_sales_refund_status(uuid, text, text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.ship_my_after_sales_replacement(uuid, text, text, text) TO authenticated;
